import fs from 'node:fs';import assert from 'node:assert/strict';import {hash,json} from './seal-simple-website-successor.mjs';
const file='CURRENT_CHECKPOINT.json',p=json(file),field='activeWork.current.pendingTourReplaySource',value=p.activeWork.current.pendingTourReplaySource,root='F:/VisibleMedicine/recovery/checkpoints/20261023-forearm-mechanics-parent-history';assert(value);assert.equal(value.fullWebsiteIntegrationPending,false);assert.equal(value.atlasHead,p.activeWork.current.latestWebsiteCandidate.atlasHead);assert.equal(p.activeWork.current.activeExecutionSessions.length,0);assert.equal(p.activeWork.current.ownerPreviewPolicy.restartPermitted,false);assert(!fs.existsSync(root));fs.mkdirSync(root);fs.copyFileSync(file,root+'/CURRENT_BEFORE.json',fs.constants.COPYFILE_EXCL);fs.writeFileSync(root+'/history.json',JSON.stringify({at:new Date().toISOString(),fields:{[field]:value},previousArchive:p.historyArchive,policy:'Original JSON paths retained; completed replay source was already composed into the current complete Website ancestry. Missing fields imply neither approval nor completion.'},null,2)+'\n',{flag:'wx'});fs.writeFileSync(root+'/field-index.json',JSON.stringify([field],null,2)+'\n',{flag:'wx'});delete p.activeWork.current.pendingTourReplaySource;p.historyArchive={path:root+'/history.json',sha256:hash(root+'/history.json'),fieldIndex:root+'/field-index.json',allHistoryRetained:true,priorArchiveIn:'previousArchive',readPolicy:'Read original JSON paths only for relevant historical facts. Missing fields imply neither approval nor completion.'};const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<65536);fs.writeFileSync(file,text);fs.copyFileSync(file,root+'/CURRENT_AFTER.json',fs.constants.COPYFILE_EXCL);console.log(JSON.stringify({history:root+'/history.json',sha256:hash(root+'/history.json'),indexBytes:Buffer.byteLength(text),goalActive:p.goal.status==='active'}));
